import fs from 'fs';
const D="<scratch>";
const B="http://localhost:8810";
const sk=JSON.parse(fs.readFileSync(D+"/shady-token.json","utf8")).key;
const dt=JSON.parse(fs.readFileSync(D+"/dana-token.json","utf8")).token;
export async function pro(action,args={}){
  const r=await fetch(B+"/a2a",{method:"POST",headers:{"content-type":"application/json",authorization:"Bearer "+sk},body:JSON.stringify({jsonrpc:"2.0",id:1,method:"message/send",params:{message:{role:"user",messageId:"m"+Math.random(),parts:[{kind:"data",data:{action,...args}}]}}})});
  const t=await r.text(); return t;
}
export async function cust(tool,args={}){
  const r=await fetch(B+"/api/agent/"+tool,{method:"POST",headers:{"content-type":"application/json",authorization:"Bearer "+dt},body:JSON.stringify(args)});
  return r.status+" "+await r.text();
}
export const dataUrl=(p)=>"data:image/jpeg;base64,"+fs.readFileSync(p).toString("base64");
export {D,B};
EOF
